            modal.id = 'kg-cookie-modal';
            modal.style.cssText = 'display: none; position: fixed; inset: 0; z-index: 9999999; background: rgba(0, 0, 0, 0.78); backdrop-filter: blur(3px); align-items: center; justify-content: center; padding: 12px; box-sizing: border-box; font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;';

